// Morning Macro — front-end renderer
// Reads static JSON files generated by GitHub Actions (data/*.json)

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => document.querySelectorAll(sel);

function fmtDateFull(d) {
  return d.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
}
function fmtTime(d) {
  return d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
}

async function fetchJSON(path) {
  try {
    const res = await fetch(path + '?t=' + Date.now());
    if (!res.ok) throw new Error(res.status);
    return await res.json();
  } catch (e) {
    console.warn('Falha ao carregar', path, e);
    return null;
  }
}

// ---------- Tabs ----------
function initTabs() {
  $$('.tab').forEach((btn) => {
    btn.addEventListener('click', () => {
      $$('.tab').forEach((b) => b.classList.remove('active'));
      $$('.tab-panel').forEach((p) => p.classList.remove('active'));
      btn.classList.add('active');
      $('#panel-' + btn.dataset.tab).classList.add('active');
    });
  });
}

// ---------- Agenda ----------
function renderAgendaItem(item) {
  const impClass = item.importance === 'high' ? 'agenda-imp-high'
    : item.importance === 'medium' ? 'agenda-imp-medium' : '';
  const div = document.createElement('div');
  div.className = 'agenda-item';
  div.innerHTML = `<span class="agenda-time">${item.time || '—'}</span>
    <span class="${impClass}">${item.title}</span>`;
  return div;
}

function renderAgenda(calendar) {
  const regions = { brasil: '#agenda-brasil', eua: '#agenda-eua', internacional: '#agenda-internacional' };
  const mini = { brasil: '#agenda-brasil-mini', eua: '#agenda-eua-mini', internacional: '#agenda-internacional-mini' };

  Object.entries(regions).forEach(([key, sel]) => {
    const container = $(sel);
    const miniContainer = $(mini[key]);
    if (!container) return;
    container.innerHTML = '';
    if (miniContainer) miniContainer.innerHTML = '';

    const items = (calendar && calendar[key]) || [];
    if (items.length === 0) {
      container.innerHTML = '<p class="empty-row" style="color:var(--text-dim);font-size:13px;">Sem eventos relevantes hoje.</p>';
      return;
    }
    items.forEach((item, idx) => {
      container.appendChild(renderAgendaItem(item));
      if (miniContainer && idx < 4) miniContainer.appendChild(renderAgendaItem(item));
    });
  });
}

// ---------- Clipping ----------
function renderClipCard(item) {
  const div = document.createElement('div');
  div.className = 'clip-card';
  div.innerHTML = `
    <div class="clip-source">${item.source}</div>
    <p class="clip-title"><a href="${item.link}" target="_blank" rel="noopener">${item.title}</a></p>
    <div class="clip-meta">${item.published || ''}</div>
  `;
  return div;
}

function renderClipping(news) {
  const regions = { brasil: '#clipping-brasil', eua: '#clipping-eua', internacional: '#clipping-internacional' };
  const miniContainer = $('#clipping-mini');
  if (miniContainer) miniContainer.innerHTML = '';

  let miniCount = 0;
  Object.entries(regions).forEach(([key, sel]) => {
    const container = $(sel);
    if (!container) return;
    container.innerHTML = '';
    const items = (news && news[key]) || [];
    if (items.length === 0) {
      container.innerHTML = '<p style="color:var(--text-dim);font-size:13px;">Sem notícias no momento.</p>';
      return;
    }
    items.forEach((item) => {
      container.appendChild(renderClipCard(item));
      if (miniContainer && miniCount < 6) {
        miniContainer.appendChild(renderClipCard(item));
        miniCount++;
      }
    });
  });
}

// ---------- Resumo ----------
function renderResumo(news, calendar) {
  const el = $('#resumo-text');
  if (!el) return;
  const headlines = []
    .concat((news && news.brasil) || [])
    .concat((news && news.eua) || [])
    .concat((news && news.internacional) || [])
    .slice(0, 3)
    .map((n) => n.title);

  if (headlines.length === 0) {
    el.textContent = 'Resumo indisponível no momento — confira a agenda e o clipping abaixo.';
    return;
  }
  el.textContent = headlines.join(' · ');
}

// ---------- Operações ----------
function renderOperacoes(ops) {
  const tbody = $('#operacoes-tbody');
  if (!tbody) return;
  tbody.innerHTML = '';
  if (!ops || ops.length === 0) {
    tbody.innerHTML = '<tr><td colspan="8" class="empty-row">Nenhuma operação cadastrada no momento.</td></tr>';
    return;
  }
  ops.forEach((op) => {
    const statusClass = 'status-' + (op.status || '').toLowerCase().replace(/\s+/g, '-');
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${op.data || ''}</td>
      <td><strong>${op.ativo || ''}</strong></td>
      <td>${op.direcao || ''}</td>
      <td>${op.entrada || ''}</td>
      <td>${op.stop || ''}</td>
      <td>${op.alvo || ''}</td>
      <td class="${statusClass}">${op.status || ''}</td>
      <td>${op.comentario || ''}</td>
    `;
    tbody.appendChild(tr);
  });
}

// ---------- Init ----------
async function init() {
  initTabs();

  const now = new Date();
  $('#date-full').textContent = fmtDateFull(now);
  $('#update-time').textContent = fmtTime(now);

  const [calendar, news, ops, meta] = await Promise.all([
    fetchJSON('data/calendar.json'),
    fetchJSON('data/news.json'),
    fetchJSON('data/operacoes.json'),
    fetchJSON('data/meta.json'),
  ]);

  if (meta && meta.updated_at) {
    const d = new Date(meta.updated_at);
    $('#date-full').textContent = fmtDateFull(d);
    $('#update-time').textContent = fmtTime(d);
  }

  renderAgenda(calendar);
  renderClipping(news);
  renderResumo(news, calendar);
  renderOperacoes(ops);
}

document.addEventListener('DOMContentLoaded', init);
